class Shape(ABC):
    @abstractmethod
    def area(self):
        pass

    @abstractmethod
    def volume(self):
        pass
class Square(Shape):
    def __init__(self, length) -> None:
        self.length = length

    def area(self):
        return self.length ** 2

    def volume(self):
        raise NotImplementedError("The volume cannot be calculated.")
class Circle(Shape):
    def __init__(self, radius) -> None:
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2

    def volume(self):
        raise NotImplementedError("The volume cannot be calculated")

